// Figma draws these on a 16px box with stroke 2 (18px box for nav), so on Lucide's 24 box that is stroke 3 (2.67 for nav).
export function icon(name, size = 16, cls = '') {
  const sw = size >= 18 ? 2.67 : 3;
  return `<svg class="ic ${cls}" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="${sw}" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${P[name] || ''}</svg>`;
}
